/// Retiming an action by dragging its band in the Clip tab's lane (spec §11
/// CI-11) — the same `ActionDragSession` the timeline drags with, through the
/// binding's live trio, so a drag is ONE undo step.
///
/// The lane selects at mouse-UP, not at the press as the timeline does: a
/// selection rebuilds the pane, and the pane must not rebuild under the
/// pointer (`refresh(isLive:)` skips rebuilds only while a live edit runs).
/// A click and a drop therefore share one path, `releaseBand`.
extension ActionLaneView {
    /// The clip time under `x`: the lane's fraction of the clip's length,
    /// clamped to the clip.
    func clipTime(atX x: CGFloat) -> Ticks {
        guard let clip = clip, clip.duration > 0 else { return 0 }
        let lane = laneRect
        guard lane.width > 0 else { return 0 }
        let fraction = min(max((x - lane.minX) / lane.width, 0), 1)
        return Ticks((Double(fraction) * Double(clip.duration)).rounded())
    }

    /// The band under `point` and the grip it is in, if any. The LAST band
    /// holding the point wins, because bands paint in time order and that is
    /// the one on top — so a zero-length band sitting on another's start is
    /// the one a press takes. A zero-length band answers too (it is
    /// selectable), always with no edge: 2 pt is all body.
    func bandHit(at point: CGPoint) -> ActionBandHover? {
        guard let clipID, let band = bandRects().last(where: { $0.rect.contains(point) })
        else { return nil }
        return ActionBandHover(
            clip: clipID, action: band.id, edge: ActionBands.gripEdge(in: band.rect, at: point.x))
    }

    /// Mouse-down in the lane. True when a band was hit; it is remembered in
    /// `pressed`, and a session starts — with `liveBegin` — ONLY for an action
    /// with a length: `duration: 0` is invalid input to the core (the
    /// `err_out` channel), not a refusal, so a zero-length band is click to
    /// select and nothing else. Nothing is selected here (CI-11).
    func pressBand(at point: CGPoint) -> Bool {
        guard let hit = bandHit(at: point) else { return false }
        pressed = hit.action
        hover = nil
        guard let clip = clip, let action = clip.actions.first(where: { $0.id == hit.action }),
              action.duration > 0
        else { return true }
        drag = ActionDragSession(
            clip: clip, action: action, mode: hit.edge.map { .resize($0) } ?? .move,
            grabAt: clipTime(atX: point.x), fps: binding.canvas.fps)
        binding.liveBegin()
        return true
    }

    /// Mouse-dragged: one `set_action` per tick; a refused tick is swallowed
    /// by `updateLiveEdit`.
    func dragBand(to point: CGPoint) {
        guard var session = drag else { return }
        session.update(clipTime: clipTime(atX: point.x))
        drag = session
        binding.liveUpdate([session.op])
        needsDisplay = true
    }

    /// Mouse-up: the drag's one undo step, if there was a drag, then the
    /// pressed band selected — a click and a drop alike, which parks the
    /// playhead at the action's (new) end.
    func releaseBand() {
        let session = drag
        let id = pressed
        drag = nil
        pressed = nil
            }
            selectClip(id, flags: flags)
            beginTrim(id, edge: edge, flags: flags)

        case .fade(let id, let edge):
            guard let clip = snapshot.clip(id) else { break }
            let props = clip.audioProps
            fadeDrag = FadeHandleSession(
                clip: id, edge: edge, clipStart: clip.start, clipEnd: clip.end,
                length: edge == .start ? props.fadeIn : props.fadeOut)
            onLiveBegin?()

        case .volumeLine(let id, let time):
            selectClip(id, flags: [])
            beginVolumeLine(id, at: point, time: time, flags: flags)

        case .action(let clip, let action):
            selectClip(clip, flags: [])
            onActionSelected?(clip, action)
            beginActionDrag(clip: clip, action: action, mode: .move, at: point)

        case .actionEdge(let clip, let action, let edge):
            selectClip(clip, flags: [])
            onActionSelected?(clip, action)
            beginActionDrag(clip: clip, action: action, mode: .resize(edge), at: point)

        case .lane(let row, let time):
            // A double-click in empty lane space closes the gap it landed
            // in. The single click AppKit delivered first started and ended
            // a marquee, which registers nothing.
            if clicks == 2 {
                closeGap(row: row, at: time)
                break
            }
            beginMarquee(at: point, flags: flags)

        case .outside:
            // Above the first lane or below the last: the same band, with
            // no row to close a gap in, so a double-click is two bands.
            beginMarquee(at: point, flags: flags)
        }

    override func draw(_ dirtyRect: NSRect) {
        guard let owner = timeline else { return }
        let layout = owner.layout
        DS.chromeBackground.setFill()
        bounds.fill()

        if let range = owner.inOutRange, range.end > range.start {
            DS.timelineRangeShade.setFill()
            NSRect(
                x: layout.x(for: range.start), y: 0,
                width: layout.width(of: range.end - range.start), height: bounds.height
            ).fill()
        }
        drawSelectedActionSpan(owner: owner, layout: layout)
        drawCandidateSpans(owner: owner, layout: layout)

        let steps = layout.rulerSteps()
        let range = layout.visibleRange(dirtyRect)
        drawTicks(steps: steps, range: range, layout: layout)
        drawMarkers(owner: owner, layout: layout)

        // The corner covers the ticks that would otherwise slide under the
        // header column, and it is drawn last for exactly that reason.
        let corner = NSRect(
            x: owner.pinnedX, y: 0, width: TimelineLayout.headerWidth, height: bounds.height)
        DS.chromeBackground.setFill()
        corner.fill()
        DS.border.setFill()
        NSRect(x: corner.maxX - 1, y: 0, width: 1, height: bounds.height).fill()
        NSRect(x: 0, y: bounds.height - 1, width: bounds.width, height: 1).fill()
        drawBreadcrumb(owner: owner, in: corner)

        drawPlayheadHead(owner: owner, layout: layout)
    }

    /// Minors and majors walk their OWN grids rather than the majors being
    /// "every nth minor".
    ///
    /// **Pitfall:** at 29.97 a frame is 20 020 ticks and a second is 600 000,
    /// which is not a multiple of it — testing `time.isMultiple(of: major)`
    /// inside the minor loop would land only on zero and the ruler would lose
    /// every label on exactly the rates that need them most.
    private func drawTicks(
        steps: (minor: Ticks, major: Ticks), range: (start: Ticks, end: Ticks),
        layout: TimelineLayout
