82	// ---- curves --------------------------------------------------------------
83	
84	/// Maps linear progress `u` (clamped to 0..1) to eased progress.
85	///
86	/// Quadratics and smoothstep, not cubic Béziers. A CSS-style Bézier is
87	/// defined as y over x with x itself a cubic, so every evaluation needs a
88	/// Newton solve for the parameter — per animated field, per frame — and the
89	/// schema would have to carry four more numbers per action. These four
90	/// closed forms hit 0 and 1 exactly, are monotone on 0..1, and cover what an
91	/// action is for (a move, a scale, a fade that does not start and stop
92	/// abruptly). If a later milestone wants arbitrary curves, `Curve` gains a
93	/// variant and this function gains an arm; nothing else changes.
94	pub fn ease(curve: Curve, u: f64) -> f64 {
95	    // NaN would propagate through every interpolated field, so it collapses
96	    // to the start of the action rather than poisoning the frame.
97	    let u = if u.is_nan() { 0.0 } else { u.clamp(0.0, 1.0) };
98	    match curve {
99	        Curve::Linear => u,
100	        Curve::EaseIn => u * u,
101	        // The mirror of ease_in, so an in/out pair is symmetric.
102	        Curve::EaseOut => 1.0 - (1.0 - u) * (1.0 - u),
103	        // Smoothstep: zero slope at both ends, which is what "ease in and
104	        // out" means, in one multiply-add more than the quadratics.
105	        Curve::EaseInOut => u * u * (3.0 - 2.0 * u),
106	    }
107	}
