111	/// Deep-merges `patch` into `base`: objects merge key by key, anything else
112	/// replaces. Keys `base` does not have are added, so a patch may introduce
113	/// a whole group (`"shadow": {...}` over a `null`); keys `patch` does not
114	/// mention are untouched. Unknown keys survive the merge and are dropped
115	/// later by serde, which is exactly the forward-compatible behaviour §5.4
116	/// asks for: never an error.
117	pub(crate) fn merge(base: &Value, patch: &Value) -> Value {
118	    merge_at(base, patch, 0)
119	}
120	
121	fn merge_at(base: &Value, patch: &Value, depth: u32) -> Value {
122	    match (base, patch) {
123	        (Value::Object(b), Value::Object(p)) if depth < MAX_PATCH_DEPTH => {
124	            let mut out = b.clone();
125	            for (key, patch_value) in p {
126	                let merged = match out.get(key) {
127	                    Some(base_value) => merge_at(base_value, patch_value, depth + 1),
128	                    None => patch_value.clone(),
129	                };
130	                out.insert(key.clone(), merged);
131	            }
132	            Value::Object(out)
133	        }
134	        _ => patch.clone(),
135	    }
136	}
