35	/// A screencast zoom's end: `video` exactly {scale, x, y}; `audio` and
36	/// `text` naming nothing; `graphic` naming no props; no numeric `speed`.
37	pub(crate) fn is_zoom(action: &Action) -> bool {
38	    let Some(video) = video(action) else {
39	        return false;
40	    };
41	    let end = &action.end;
42	    let graphic_quiet = match end.get("graphic") {
43	        None | Some(Value::Null) => true,
44	        Some(g) => names_nothing(g.get("props")),
45	    };
46	    let no_speed = !end.get("speed").is_some_and(Value::is_number);
47	    video.len() == 3
48	        && ["scale", "x", "y"].iter().all(|k| video.contains_key(*k))
49	        && names_nothing(end.get("audio"))
50	        && names_nothing(end.get("text"))
51	        && graphic_quiet
52	        && no_speed
53	}
