13	    COMPRESSOR_MAKEUP_MAX_DB, COMPRESSOR_RATIO_MAX, COMPRESSOR_THRESHOLD_MIN_DB, EXPOSURE_MAX,
14	    LIMITER_CEILING_MIN_DB, LIMITER_RELEASE_MAX, LIMITER_RELEASE_MIN, SCALE_MAX, SCALE_MIN,
15	    SPOT_ZOOM_MAX, TONE_MAX, WORD_SCALE_MAX, WORD_SCALE_MIN,
