50	/// `is_nest` is what a NEST clip's evaluated props are held to, and it is
51	/// the only thing here that is not a range: a nest cannot blend (format
52	/// version 6), and this is where that holds for good.
53	pub(crate) fn clamp_video(mut props: VideoProps, is_nest: bool) -> VideoProps {
54	    props.x = finite_or(props.x, 0.0);
55	    props.y = finite_or(props.y, 0.0);
56	    props.scale = bounded(props.scale, SCALE_MIN, SCALE_MAX, 1.0);
57	    props.rotation = finite_or(props.rotation, 0.0);
58	    props.opacity = bounded(props.opacity, 0.0, 1.0, 1.0);
59	    props.corner_radius = bounded(props.corner_radius, 0.0, f64::MAX, 0.0);
60	    props.crop.l = bounded(props.crop.l, 0.0, f64::MAX, 0.0);
61	    props.crop.t = bounded(props.crop.t, 0.0, f64::MAX, 0.0);
62	    props.crop.r = bounded(props.crop.r, 0.0, f64::MAX, 0.0);
63	    props.crop.b = bounded(props.crop.b, 0.0, f64::MAX, 0.0);
64	    if let Some(shadow) = props.shadow.as_mut() {
65	        for channel in shadow.color.iter_mut() {
66	            *channel = bounded(*channel, 0.0, 1.0, 0.0);
67	        }
68	        shadow.opacity = bounded(shadow.opacity, 0.0, 1.0, 0.5);
69	        shadow.blur = bounded(shadow.blur, 0.0, f64::MAX, 0.0);
70	        shadow.angle = finite_or(shadow.angle, 315.0);
71	        shadow.distance = bounded(shadow.distance, 0.0, f64::MAX, 0.0);
72	    }
73	    props.color.brightness = finite_or(props.color.brightness, 0.0);
74	    props.color.contrast = finite_or(props.color.contrast, 0.0);
75	    props.color.saturation = finite_or(props.color.saturation, 0.0);
76	    props.color.hue = finite_or(props.color.hue, 0.0);
77	    let tone = &mut props.color;
78	    tone.exposure = bounded(tone.exposure, -EXPOSURE_MAX, EXPOSURE_MAX, 0.0);
79	    tone.temperature = bounded(tone.temperature, -TONE_MAX, TONE_MAX, 0.0);
80	    tone.tint = bounded(tone.tint, -TONE_MAX, TONE_MAX, 0.0);
81	    tone.highlights = bounded(tone.highlights, -TONE_MAX, TONE_MAX, 0.0);
82	    tone.shadows = bounded(tone.shadows, -TONE_MAX, TONE_MAX, 0.0);
83	    tone.whites = bounded(tone.whites, -TONE_MAX, TONE_MAX, 0.0);
84	    tone.blacks = bounded(tone.blacks, -TONE_MAX, TONE_MAX, 0.0);
85	    tone.vibrance = bounded(tone.vibrance, -TONE_MAX, TONE_MAX, 0.0);
86	    tone.fade = bounded(tone.fade, 0.0, TONE_MAX, 0.0);
87	    clamp_wheels(&mut props.wheels);
88	    clamp_curves(&mut props.curves);
89	    clamp_qualifier(&mut props.qualifier);
90	    // A NaN amount is none of the look, the neutral a filter's amount has.
91	    if let Some(look) = props.look.as_mut() {
92	        look.amount = bounded(look.amount, 0.0, 1.0, 0.0);
93	    }
94	    if let Some(chroma) = props.chroma.as_mut() {
95	        for channel in chroma.key.iter_mut() {
96	            *channel = bounded(*channel, 0.0, 1.0, 0.0);
97	        }
98	        chroma.tolerance = bounded(chroma.tolerance, 0.0, 1.0, 0.0);
99	        chroma.softness = bounded(chroma.softness, 0.0, 1.0, 0.0);
100	        chroma.spill = bounded(chroma.spill, 0.0, 1.0, 0.0);
101	    }
102	    // The shader budget is a hard limit on the recipe, not a preference:
103	    // a fifth filter has no uniform slot to arrive in, and the extras are
104	    // dropped from the END so the ones the user put first survive.
105	    props.filters.truncate(MAX_FILTERS);
106	    for filter in props.filters.iter_mut() {
107	        filter.amount = bounded(filter.amount, 0.0, 1.0, 0.0);
108	    }
109	    if let Some(reflection) = props.reflection.as_mut() {
110	        reflection.opacity = bounded(reflection.opacity, 0.0, 1.0, 0.35);
111	        reflection.height = bounded(reflection.height, 0.0, 1.0, 0.5);
112	        reflection.gap = bounded(reflection.gap, 0.0, f64::MAX, 0.0);
113	        reflection.falloff = bounded(reflection.falloff, 0.0, 1.0, 1.0);
114	    }
115	    if let Some(spotlight) = props.spotlight.as_mut() {
116	        spotlight.x = finite_or(spotlight.x, 0.0);
117	        spotlight.y = finite_or(spotlight.y, 0.0);
118	        // A zero-sized region would divide by nothing in the shader's
119	        // distance field, so the floor is a pixel rather than 0.
120	        spotlight.width = bounded(spotlight.width, 1.0, f64::MAX, 480.0);

