38	/// The audio numbers that switch at an action's end rather than glide
39	/// (AU-86), as JSON pointers into the evaluated state.
40	pub(crate) const HELD_AUDIO_NUMBERS: [&str; 5] = [
41	    "/audio/eq/high_pass/slope",
42	    "/audio/eq/low_pass/slope",
43	    "/audio/hum/frequency",
44	    "/audio/hum/harmonics",
45	    "/audio/leveller/response",
46	];
