48	/// Puts each [`HELD_AUDIO_NUMBERS`] field of `lerped` back to its value in
49	/// `from`, the state the spanning action started from. Only where both have
50	/// it: a slot present on one side alone already holds or switches whole
51	/// through `lerp`'s mismatched-type rule.
52	pub(crate) fn hold_audio_steps(from: &Value, lerped: &mut Value) {
53	    for pointer in HELD_AUDIO_NUMBERS {
54	        let Some(start) = from.pointer(pointer) else {
55	            continue;
56	        };
57	        if let Some(slot) = lerped.pointer_mut(pointer) {
58	            *slot = start.clone();
59	        }
60	    }
61	}
