138	/// Interpolates `from` toward `to` by eased progress `u`.
139	///
140	/// Numbers interpolate; arrays (`from`/`to` points, the filter and obscure
141	/// lists) interpolate element by element when the lengths match; objects
142	/// interpolate key by key. Colours lerp element by element here too, and
143	/// `actions_color.rs`'s `blend_colors` then overwrites them with the OKLab
144	/// blend of the two ends (spec §11 G-43). **Booleans, strings,
145	/// enums, `null`s and any pair of mismatched types switch at the END** —
146	/// they hold the `from` value until `u` reaches 1 — which is the §5.4 rule
147	/// and the only sane reading of "interpolate `left` to `center`".
148	///
149	/// # The list rule
150	///
151	/// Written out here because it is now the CRATE's rule rather than one
152	/// list's: **an end patch interpolates a list PER INDEX when the lengths
153	/// match and each pair of entries agrees on its discrete fields, and
154	/// switches at the end otherwise.** `video.filters` was the schema's first
155	/// array of objects and `video.obscure` (format version 4) is the second,
156	/// both governed by exactly this and neither carrying a line of its own
157	/// code. An animation over a list is invisible until somebody writes one,
158	/// so the two consequences are worth stating outright:
159	///
160	///  - **Lists of different lengths switch at the end.** Blur alone toward
161	///    blur-plus-vignette has no correspondence between the elements: the
162	///    only alternative is to invent an off-strength vignette to grow from,
163	///    which is a guess about what the second list means, and a wrong guess
164	///    would animate a filter the user never asked to see.
165	///  - **Entries that NAME different things switch at the end too**, even
166	///    when the lengths match — the [`ENTRY_DISCRIMINANTS`] rule, applied by
167	///    [`lerp_entry`]. Entries that agree, and entries whose patch side
168	///    names neither key, interpolate their numbers, which is the case that
169	///    matters: an action that ramps a blur from 0 to 1 is exactly "grow
170	///    this filter", and it works. The hold is PER ENTRY — a list in which
171	///    one region changes shape still interpolates every region beside it,
172	///    because the list's correspondence is intact and only that one
173	///    entry's is not.
174	fn lerp(from: &Value, to: &Value, u: f64) -> Value {
175	    lerp_at(from, to, u, 0)
176	}
177	
178	/// The keys that name WHAT a list entry is rather than how much of it there
179	/// is: a filter's `kind`, an obscure region's `kind` and its `shape`.
180	///
181	/// The wider set is deliberately confined to LIST ENTRIES; the object rule
182	/// in [`lerp_at`] still knows `kind` alone. That is not a compromise, it is
183	/// the distinction the two cases actually have. In a list, an entry's only
184	/// identity is its INDEX: when entry 1 comes back as a different shape of
185	/// region there is nothing to say whether the user reshaped that region or
186	/// replaced it, so morphing one into the other invents a correspondence.
187	/// On a named object there is no such doubt — `video.spotlight` is one
188	/// spotlight, `shape` is a property OF it, and an action that moves it from
189	/// a rect to an ellipse is still moving that spotlight's centre and box.
190	/// Widening the object rule to `shape` would have frozen the geometry of
191	/// every such animation until the last instant and then jumped it: a silent
192	/// change to shipped behaviour, in a feature phase 3 has nothing to do
193	/// with. `core/tests/schema_v2.rs` pins both halves.
194	const ENTRY_DISCRIMINANTS: [&str; 2] = ["kind", "shape"];
195	
196	/// The keys that name WHAT a named object is: `kind` (a filter's, a
197	/// shape's, a transition's, a look's) and `media`, a LUT look's file (spec
198	/// §11 GR-8). An id is a name, not a quantity: a LUT A → B interpolated
199	/// would pass through whichever media sits between the two ids, so the
200	/// look switches at the end instead, as a change of kind does. The rule
201	/// applies to any object at any depth of an action's state; `video.look` is
202	/// the only object with a `media` key today, so a group that adds one
203	/// switches it at the end too.
204	const OBJECT_DISCRIMINANTS: [&str; 2] = ["kind", "media"];
205	
206	/// One entry of a list toward the entry at the same index —
207	/// [`lerp_at`] under the wider [`ENTRY_DISCRIMINANTS`] set.
208	///
209	/// Only [`lerp_at`]'s array arm calls this, which is what keeps the switch
210	/// point in ONE place: by the time an entry is reached `u` is strictly
211	/// inside the span, because the whole list has already gone to `to` at
212	/// `u >= 1.0` and held at `from` at `u <= 0.0`. So holding an entry here
213	/// holds it for the whole span, and the end still switches — no second copy
214	/// of the two guards, which would be a second place to get them wrong.
215	fn lerp_entry(from: &Value, to: &Value, u: f64, depth: u32) -> Value {
216	    if let (Value::Object(a), Value::Object(b)) = (from, to) {
217	        // Both sides must name a discriminant for this to fire, so a patch
218	        // entry that leaves them out — `{"filters": [{"amount": 1}]}`,
219	        // "same filter, more of it" — still interpolates, key by key.
220	        let names_another_thing = ENTRY_DISCRIMINANTS
221	            .iter()
222	            .any(|key| matches!((a.get(*key), b.get(*key)), (Some(x), Some(y)) if x != y));
223	        if names_another_thing {
224	            return from.clone();
225	        }
226	    }
227	    lerp_at(from, to, u, depth)
228	}
229	
230	fn lerp_at(from: &Value, to: &Value, u: f64, depth: u32) -> Value {
231	    // The two switch points. `u >= 1.0` is what makes non-numeric fields
232	    // take their new value at the action's end and not one tick earlier.
233	    if u >= 1.0 {
234	        return to.clone();
235	    }
236	    if u <= 0.0 || depth >= MAX_PATCH_DEPTH {
237	        return from.clone();
238	    }
239	    match (from, to) {
240	        (Value::Number(a), Value::Number(b)) => lerp_number(a, b, u),
241	        // Elements go through `lerp_entry`, which is this function under a
242	        // wider discriminant set — the list rule, stated in full on [`lerp`].
243	        (Value::Array(a), Value::Array(b)) if a.len() == b.len() => Value::Array(
244	            a.iter()
245	                .zip(b.iter())
246	                .map(|(x, y)| lerp_entry(x, y, u, depth + 1))
247	                .collect(),
248	        ),
249	        // A `kind` is a DISCRIMINANT everywhere in §5.2 — a filter's kind,
250	        // a shape's, a transition's — so two objects that NAME different
251	        // ones are two different things, and the numbers beside them do not
252	        // measure the same quantity. Interpolating them would read a blur's
253	        // strength as a sepia's. The whole object switches at the end
254	        // instead, exactly as the string naming it would on its own.
255	        //
256	        // Both sides must name one for this to fire, so a patch element
257	        // that leaves `kind` out — `{"filters": [{"amount": 1}]}`, "same
258	        // filter, more of it" — still interpolates, key by key, below.
259	        //
260	        // `kind` and a look's `media` are the discriminants here
261	        // ([`OBJECT_DISCRIMINANTS`]). A list ENTRY is judged against
262	        // [`ENTRY_DISCRIMINANTS`] before it ever reaches this arm, and that
263	        // constant argues why the two sets differ.
264	        (Value::Object(a), Value::Object(b))
265	            if OBJECT_DISCRIMINANTS
266	                .iter()
267	                .any(|key| matches!((a.get(*key), b.get(*key)), (Some(x), Some(y)) if x != y)) =>
268	        {
269	            from.clone()
270	        }
271	        (Value::Object(a), Value::Object(b)) => {
272	            let mut out = Map::new();
273	            for (key, from_value) in a {
274	                let value = match b.get(key) {
275	                    Some(to_value) => lerp_at(from_value, to_value, u, depth + 1),
276	                    // A key the target lost: nothing to move toward.
277	                    None => from_value.clone(),
278	                };
279	                out.insert(key.clone(), value);
280	            }
281	            Value::Object(out)
282	        }
283	        _ => from.clone(),
284	    }
285	}
