287	/// One number toward another.
288	///
289	/// The integer case matters: `fade_in`, `fade_out` and the duck ramps are
290	/// `Ticks` (i64) in the schema, and writing 12.5 back into one of those
291	/// would fail to deserialize. So a pair that is integral on BOTH sides
292	/// stays integral (rounded), and anything touching a float stays float —
293	/// which is always the case for the f64 fields, because the base state is
294	/// serialized from the typed structs.
295	fn lerp_number(from: &Number, to: &Number, u: f64) -> Value {
296	    let (Some(a), Some(b)) = (from.as_f64(), to.as_f64()) else {
297	        return Value::Number(from.clone());
298	    };
299	    let value = a + (b - a) * u;
300	    if from.is_f64() || to.is_f64() {
301	        // from_f64 rejects NaN and infinities; falling back to `from` keeps
302	        // a nonsense patch from turning the whole frame into null.
303	        Number::from_f64(value)
304	            .map(Value::Number)
305	            .unwrap_or_else(|| Value::Number(from.clone()))
306	    } else {
307	        // Rust's float-to-int cast saturates, so an absurd patch cannot
308	        // panic here.
309	        Value::Number(Number::from(value.round() as i64))
310	    }
311	}
