340	/// A clip's `color` with ALL thirteen keys, tone's nine included at 0 —
341	/// where `to_json` leaves a neutral tone key out, as the file does (spec §11
342	/// GR-2). Every reader that walks keys needs them present: an action's
343	/// [`lerp_at`] walks only its FROM side's keys, so a neutral key absent
344	/// there would drop out mid-action and jump at the end; `patch.rs`'s
345	/// template would refuse `color.exposure` as unknown; and the recipe's
346	/// `color` is the compositor's, which `clip_state` must equal.
347	pub(crate) fn color_json(color: &ColorAdjust) -> Value {
348	    let keys = [
349	        ("brightness", color.brightness),
350	        ("contrast", color.contrast),
351	        ("saturation", color.saturation),
352	        ("hue", color.hue),
353	        ("exposure", color.exposure),
354	        ("temperature", color.temperature),
355	        ("tint", color.tint),
356	        ("highlights", color.highlights),
357	        ("shadows", color.shadows),
358	        ("whites", color.whites),
359	        ("blacks", color.blacks),
360	        ("vibrance", color.vibrance),
361	        ("fade", color.fade),
362	    ];
363	    let mut out = Map::new();
364	    for (key, value) in keys {
365	        out.insert(key.to_string(), to_json(&value));
366	    }
367	    Value::Object(out)
