370	/// The wheels with every key present (spec §11 GR-11): all three wheels and
371	/// each one's `x`, `y` and `master`, even at 0, which the file leaves out.
372	pub(crate) fn wheels_json(wheels: &Wheels) -> Value {
373	    let mut out = Map::new();
374	    for (name, wheel) in wheels.named() {
375	        let mut keys = Map::new();
376	        keys.insert("x".to_string(), to_json(&wheel.x));
377	        keys.insert("y".to_string(), to_json(&wheel.y));
378	        keys.insert("master".to_string(), to_json(&wheel.master));
379	        out.insert(name.to_string(), Value::Object(keys));
380	    }
