18	/// Brings an evaluated value back into the range the ops enforce.
19	///
20	/// An action's end patch is deliberately LENIENT — `set_action_end` merges
21	/// whatever it is given so a half-written animation is still editable — and
22	/// interpolation can also overshoot nothing but reach a bad target. Nobody
23	/// downstream can defend itself: the Metal compositor multiplies by opacity
24	/// and scales a quad, and `audio.rs` would fold a nonsense gain into an
25	/// envelope. So the ONE place an evaluated value is produced is the one
26	/// place it is bounded, using the SAME table `props_check.rs` holds for a
27	/// direct edit (there a check errors and names the key, because a user typed
28	/// it; here there is nobody to tell, so it clamps).
29	///
30	/// NaN collapses to the neutral value rather than propagating: a single NaN
31	/// in a uniform block blanks a whole frame.
32	pub(crate) fn bounded(value: f64, low: f64, high: f64, neutral: f64) -> f64 {
33	    if value.is_nan() {
34	        neutral
35	    } else {
36	        value.clamp(low, high)
37	    }
38	}
