40	/// Finite-only guard for the fields that have no range, just a requirement
41	/// that they be numbers (positions, rotation, the colour offsets).
42	fn finite_or(value: f64, neutral: f64) -> f64 {
43	    if value.is_finite() {
44	        value
45	    } else {
46	        neutral
47	    }
48	}
