//! `set_action_end`'s END patch door, moved whole out of `edit_action.rs`
//! (road map "creator-jobs" CO2a1's toll, a pure move): [`check_end_patch`],
//! the walk of an end patch's three groups; [`not_a_target`], the keys an
//! action may not animate; [`prune_removed`], a `null`'s removal from the
//! stored end; and `off` (spec §11 CI-14) — [`check_off`] reading its paths
//! and [`key_off`] writing each one's `null`. `edit_action.rs` composes them
//! in `set_action_end`; `END_PATCH` is also `edit_action_graphic.rs`'s.

use serde_json::{json, Map, Value};

use crate::actions::MAX_PATCH_DEPTH;
use crate::edit_action_graphic::GRAPHIC_NOT_KEYED_OFF;
use crate::model::{AudioProps, ShapeProps, TextProps, VideoProps};
use crate::patch::{check_group_patch, merge_group, unknown_key, Group};

/// Removes from `value` every key the incoming `patch` set to `null` —
/// `set_action_end`'s delete rule (spec §6). Only keys the patch mentions
/// are touched, so a `null` that was already in the end patch (animating a
/// shadow away, say) survives untouched. `shift_remove`, because under
/// `preserve_order` `Map::remove` swaps the last key into the hole.
pub(crate) fn prune_removed(value: &mut Value, patch: &Value, depth: u32) {
    let Value::Object(patched) = patch else {
        return;
    };
    let Value::Object(target) = value else {
        return;
    };
    if depth >= MAX_PATCH_DEPTH {
        return;
    }
    for (key, sub) in patched {
        if sub.is_null() {
            target.shift_remove(key);
        } else if let Some(slot) = target.get_mut(key) {
            prune_removed(slot, sub, depth + 1);
        }
    }
}

/// What a refusal calls this op's patch. It is not one group's — the paths
/// inside it carry the group's name (`video.filters[1].kind`) — so it
/// cannot be a `Group`'s own subject.
pub(crate) const END_PATCH: &str = "an action end patch";

/// The groups §5.4's end patch may name. `shape` is not among them, and its
/// absence is a refusal rather than an omission: `evaluate_clip` passes a
/// clip's shape through untouched, so the key would be stored, reported as
/// success and animate nothing.
const END_GROUPS: [Group; 3] = [Group::Video, Group::Audio, Group::Text];

/// Walks an end patch's keys, kinds and values the way every other patch
/// is walked (`patch.rs`'s `check_group_patch`), group by group, and
/// refuses by the dotted path.
///
/// What belongs to THIS door rather than to a property group, and is why
/// the walk is composed here rather than called:
///
/// - **Three groups and no fourth.** Spec §5.4's patch is a subset of
///   `video`, `audio` and `text`. `shape` is refused rather than kept,
///   because `evaluate_clip` passes a clip's shape through untouched: the
///   key would be stored, reported as success, and animate nothing.
/// - **A `null` is a REMOVAL at every depth**, not a clear. The walk sees
///   it (so `{"video": {"blurr": null}}` is still an unknown key) and the
///   typed read does not (so `{"video": {"crop": null}}` is "stop animating
///   the crop" rather than a required field being cleared) —
///   `check_group_patch` is where that split lives, and [`prune_removed`]
///   below applies the same rule to the STORED end state.
pub(crate) fn check_end_patch(patch: &Value) -> Result<(), String> {
    let Value::Object(groups) = patch else {
        return Ok(());
    };
    for (key, body) in groups {
        // `graphic` is `edit_action_graphic.rs`'s arm and `speed`
        // `edit_action_speed.rs`'s, each read after this walk.
        if key == "graphic" || key == "speed" {
            continue;
        }
        // The three groups, by their own names rather than by three string
        // literals: a group renamed in `patch.rs` cannot drift from the
        // door that lists it.
        let group = END_GROUPS
            .into_iter()
            .find(|group| group.name() == key)
            .ok_or_else(|| unknown_key(key, END_PATCH))?;
        // A group set to `null` removes the whole group from the end state,
        // which is the same removal one key deep.
        if body.is_null() {
            continue;
        }
        check_group_patch(body, group, END_PATCH, key)?;
    }
    Ok(())
}

/// The two refusals that are about this op rather than the vocabulary,
/// asked of a group and a key wherever they came from — a `patch`'s keys
/// and an `off` path go through the same two sentences. The third arm is
/// `off`'s alone: a cutout's presence is the clip's own (spec §11 CO-20),
/// so an end may not take it away; a `patch` naming `video.cutout` is
/// [`check_cutout_end`]'s.
pub(crate) fn not_a_target(group: &str, key: &str) -> Result<(), String> {
    match (group, key) {
        ("video", "motion") => Err("video.motion is not an animation target".to_string()),
        ("video", "hide_silent") => Err("video.hide_silent is not an animation target".to_string()),
        ("text", "words") => Err("text.words is not an animation target".to_string()),
        ("video", "cutout") => Err("video.cutout cannot be keyed off at an action's end; \
                                    set_video {cutout: null} removes it"
            .to_string()),
        _ => Ok(()),
    }
}

/// A `patch`'s `video.cutout` naming `subject` or `quality` — a `null`
/// included, `subject` asked first — refused by name (spec §11 CO-20): which
/// subject and which masks are the clip's own, and the evaluator restores
/// the base's over any end (`cutout_check.rs`'s `restore_base_cutout`).
/// `edge`, `feather` and `background` pass; anything that is not an object
/// is the walk's to judge.
pub(crate) fn check_cutout_end(patch: &Value) -> Result<(), String> {
    let Some(Value::Object(cutout)) = patch.get("video").and_then(|video| video.get("cutout"))
    else {
        return Ok(());
    };
    for key in ["subject", "quality"] {
        if cutout.contains_key(key) {
            return Err(format!("video.cutout.{key} is not an animation target"));
        }
    }
    Ok(())
}

/// The EQ's seven slots, the one group whose slot `off` may name (AU-88).
#[rustfmt::skip]
const EQ_SLOTS: [&str; 7] =
    ["high_pass", "low_shelf", "band_1", "band_2", "band_3", "high_shelf", "low_pass"];

/// One `off` path: `group.key`, or `audio.eq.<slot>` with its `slot`.
pub(crate) struct OffPath<'a> {
    group: &'a str,
    key: &'a str,
        spotlight.width = bounded(spotlight.width, 1.0, f64::MAX, 480.0);
        spotlight.height = bounded(spotlight.height, 1.0, f64::MAX, 270.0);
        spotlight.feather = bounded(spotlight.feather, 0.0, f64::MAX, 0.0);
        spotlight.dim = bounded(spotlight.dim, 0.0, 1.0, 0.6);
        spotlight.zoom = bounded(spotlight.zoom, 1.0, SPOT_ZOOM_MAX, 1.0);
    }
    // The regions are the filter list's story with a sharper ending: a
    // fifth region has no uniform slot either, and what a dropped one costs
    // is not an effect the user cannot see but the face they hid, back on
    // screen. `set_video` NAMES the overflow rather than trimming it for
    // that reason; here there is nobody to tell, so the extras go from the
    // end and the ones drawn first survive.
    props.obscure.truncate(MAX_OBSCURE);
    for region in props.obscure.iter_mut() {
        region.x = finite_or(region.x, 0.0);
        region.y = finite_or(region.y, 0.0);
        // A zero-sized region divides by nothing in the shader's distance
        // field, exactly as the spotlight's does, so the floor is a pixel.
        region.width = bounded(region.width, 1.0, f64::MAX, 480.0);
        region.height = bounded(region.height, 1.0, f64::MAX, 270.0);
        region.feather = bounded(region.feather, 0.0, f64::MAX, 0.0);
        // NaN takes the type's own default, full strength — a neutral
        // chosen for what it PREVENTS rather than for changing nothing, as
        // a filter's 0 is. An amount that arrived as a NaN and resolved to
        // "hides nothing" would quietly publish the face it was drawn over.
        region.amount = bounded(region.amount, 0.0, 1.0, 1.0);
    }
    // The nest rule, closed here rather than only at the op. `set_video`
    // refuses a blend on a nest clip by name (`edit_props.rs`'s
    // `check_blend`), but an action's `end` patch is checked against the
    // VOCABULARY and never against the clip (`edit_action.rs`), and
    // `multiply` is a perfectly legal mode, so
    // `set_action_end {"video": {"blend": "multiply"}}` would otherwise
    // sail past every check the op path has and reach the uniform block
    // anyway. Forcing it in the evaluator closes the recipe,
    // `clip_state` and both export writers at once, which no per-op check
    // can — this is the ONE place an evaluated value is produced.
    //
    // Why a nest cannot blend at all is `check_blend`'s doc: a nest is
    // flattened into one layer per clip inside it, so there is no composite
    // of its own for a blend to combine with the canvas.
    if is_nest {
        props.blend = BlendMode::Normal;
    }
    crate::cursor_props::clamp_cursor(&mut props.cursor);
    crate::cutout_check::clamp_cutout(&mut props.cutout);
    props.motion_blur = crate::motion_blur::clamp_motion_blur(props.motion_blur);
    props
}

pub(crate) fn clamp_audio(mut props: AudioProps) -> AudioProps {
    props.volume = bounded(props.volume, 0.0, MAX_GAIN, 1.0);
    props.fade_in = props.fade_in.max(0);
    props.fade_out = props.fade_out.max(0);
    if let Some(duck) = props.duck.as_mut() {
        duck.level = bounded(duck.level, 0.0, 1.0, 0.2);
        duck.attack = duck.attack.max(0);
        duck.release = duck.release.max(0);
        duck.pre_roll = duck.pre_roll.max(0);
        duck.hold = duck.hold.max(0);
    }
    // Pan's neutral is the CENTRE, not either end: a NaN that silently
    // threw the voice into one speaker would be worse than one that did
    // nothing.
    props.pan = bounded(props.pan, -1.0, 1.0, 0.0);
    props.noise_reduction = bounded(props.noise_reduction, 0.0, 1.0, 0.0);
    props.isolation = bounded(props.isolation, 0.0, 1.0, 0.0);
    if let Some(compressor) = props.compressor.as_mut() {
        compressor.threshold_db = bounded(
            compressor.threshold_db,
            COMPRESSOR_THRESHOLD_MIN_DB,
            0.0,
            -18.0,
        );
        compressor.ratio = bounded(compressor.ratio, 1.0, COMPRESSOR_RATIO_MAX, 3.0);
        compressor.attack = compressor.attack.max(0);
        compressor.release = compressor.release.max(0);
        compressor.makeup_db = bounded(compressor.makeup_db, 0.0, COMPRESSOR_MAKEUP_MAX_DB, 0.0);
    }
    if let Some(limiter) = props.limiter.as_mut() {
        limiter.ceiling_db = bounded(limiter.ceiling_db, LIMITER_CEILING_MIN_DB, 0.0, -1.0);
        limiter.release = limiter
            .release
            .clamp(LIMITER_RELEASE_MIN, LIMITER_RELEASE_MAX);
    }
    props.eq = props.eq.map(crate::audio_eq::clamp_eq);
    props.hum = props.hum.map(crate::audio_eq::clamp_hum);
    props.gate = props.gate.map(crate::audio_dynamics::clamp_gate);
    props.de_esser = props.de_esser.map(crate::audio_dynamics::clamp_de_esser);
    props.leveller = props.leveller.map(crate::audio_dynamics::clamp_leveller);
    if let Some(voice) = props.voice.as_mut() {
        voice.amount = bounded(voice.amount, 0.0, 1.0, 1.0);
        voice.pitch = voice.pitch.map(|p| bounded(p, -12.0, 12.0, 0.0));
    }
    props
}

/// One colour's channels to 0..1, a NaN channel to that channel of
/// `neutral` — the colour's own default, so a NaN never blanks or tints
/// the layer it paints.
fn clamp_color(color: Color, neutral: Color) -> Color {
    let mut out = color;
    for (i, channel) in out.iter_mut().enumerate() {
        *channel = bounded(*channel, 0.0, 1.0, neutral[i]);
    }
    out
}

/// The text group, bounded as `clamp_video` bounds the picture: every NaN
/// to its field's own default, every other number into the range
/// `props_check.rs`'s `check_text` holds a direct edit to.
///
/// A value `check_text` accepts passes unchanged, with ONE exception: a
/// size in (0, 1) is raised to 1.0, the size Swift already draws it at
/// (`max(1, size)` in the text and word renderers) — the spotlight's pixel
/// floor is the precedent. `width` is floored at `f64::MIN_POSITIVE`, not
/// 1.0, so a legal width in (0, 1) is NOT an exception: the renderer sizes
/// its texture from the unfloored value, and a 1.0 floor would change the
/// picture of a width the op accepts.
///
/// `words` and `animation` are left alone: `set_action_end` refuses
/// `text.words` as a target, and `recipe_text.rs`'s `ramp` bounds the
/// animation where it is consumed.
///
/// Check and clamp stay two tables on purpose (#353): a check names the key
/// and refuses, a clamp has nobody to tell, and their neutrals, floors and
/// list policies differ.
///
/// The neutrals are written as literals rather than read from
/// `TextProps::default()`, which allocates a `String` on every evaluation;
/// each one names the `Default` it mirrors.
pub(crate) fn clamp_text(mut props: TextProps) -> TextProps {
    // `TextProps::default`'s size, colour, line spacing and tracking.
    props.size = bounded(props.size, 1.0, f64::MAX, 72.0);
    props.color = clamp_color(props.color, [1.0, 1.0, 1.0, 1.0]);
    // Not a positive floor: the renderer already draws a spacing of 0 or
    // less as the font's natural spacing, so mapping it to 1.0 draws the
    // same picture, where a floor such as 0.01 would change it.
    if !(props.line_spacing.is_finite() && props.line_spacing > 0.0) {
        props.line_spacing = 1.0;
    }
    props.tracking = finite_or(props.tracking, 0.0);
    // `Outline::default`.
    if let Some(outline) = props.outline.as_mut() {
        outline.width = bounded(outline.width, 0.0, f64::MAX, 2.0);
        outline.color = clamp_color(outline.color, [0.0, 0.0, 0.0, 1.0]);
    }
    // `Backdrop::default`.
    if let Some(backdrop) = props.backdrop.as_mut() {
        backdrop.color = clamp_color(backdrop.color, [0.0, 0.0, 0.0, 0.6]);
        backdrop.padding = bounded(backdrop.padding, 0.0, f64::MAX, 12.0);
        backdrop.radius = bounded(backdrop.radius, 0.0, f64::MAX, 8.0);
    }
    // A NaN width is `TextProps::default`'s `None`, a single line; any
    // other is kept above 0, the bound `check_text` holds.
    props.width = match props.width {
        Some(width) if width.is_nan() => None,
        Some(width) => Some(width.clamp(f64::MIN_POSITIVE, f64::MAX)),
        None => None,
    };
    // `WordStyle::default`'s scale and dim, `WordStyle::template`'s colours
    // and `ActivePill::default`'s plate.
    if let Some(style) = props.word_style.as_mut() {
        style.active_scale = bounded(style.active_scale, WORD_SCALE_MIN, WORD_SCALE_MAX, 1.0);
        style.pause_dim = bounded(style.pause_dim, 0.0, 1.0, 0.0);
        for color in [
            &mut style.active_color,
            &mut style.spoken_color,
            &mut style.upcoming_color,
        ] {
            if let Some(c) = color.as_mut() {
                *c = clamp_color(*c, [1.0, 1.0, 1.0, 1.0]);
            }
        }
        if let Some(pill) = style.active_pill.as_mut() {
            pill.color = clamp_color(pill.color, [0.55, 0.27, 0.93, 1.0]);
            pill.padding = bounded(pill.padding, 0.0, f64::MAX, 0.2);
            pill.radius = bounded(pill.radius, 0.0, f64::MAX, 0.25);
        }
    }
    props
            }
        }
        if let Some(action) = actions.iter().find(|a| spans(a, clip_t)) {
            // Interpolating the WHOLE state toward the patched state, not
            // just the patched keys, is what keeps this to one routine:
            // an untouched field lerps from itself to itself, exactly.
            let mut target = merge(&state, &action.end);
            // An identity curve meeting a curve of another count takes its
            // x's, so a grade animates from (or to) neutral (spec §11 GR-12).
            align_identity_curves(&mut state, &mut target);
            // The hue centre the short way round (spec §11 GR-13).
            align_hue_center(&mut state, &mut target);
            let elapsed = clip_t.saturating_sub(action.start) as f64;
            let progress = elapsed / action.duration as f64;
            let eased = ease(action.curve, progress);
            let mut lerped = lerp(&state, &target, eased);
            // The colours in OKLab from the two ends (spec §11 G-43).
            blend_colors(&state, &target, eased, &mut lerped);
            hold_audio_steps(&state, &mut lerped);
            state = lerped;
            spanning = Some((target, eased));
        }

        // Motion is NOT an animation target (format version 8, spec §5.4).
        // `set_action_end` refuses a patch naming it, but a hand-written
        // file, a pasted action or another tool's project reaches here
        // without passing that op, so the BASE value goes back over what
        // the loop reached — at the `Value` level, since `clamp_video` is
        // never handed the base props and a malformed `motion` would fail the
        // WHOLE video group's decode below, losing every other animated one. The guard is "no input may panic" applied to a value
        // nothing validates: `merge_at` REPLACES on a type mismatch, and
        // `set_action_end` checks only the patch's top level, so
        // `state["video"]` may be a number, string, array, bool or null
        // here — and `IndexMut<&str>` panics on all but null, where it would
        // MINT `{"motion": …}` and decode as DEFAULT props rather than base.
        // With the `if let` each keeps falling through to
        // `.ok().unwrap_or(base_video)`, as it always did.
        //
        // A look that does not read as one becomes no look (spec §11 GR-7),
        // in the same place and for the same reason. `set_action_end` checks
        // an end against the patch TEMPLATE, whose look has a kind, so an end
        // of `{"look": {"amount": 1}}` is accepted — and on a clip with no
        // look (or one whose look was removed after the end was written) the
        // merge leaves a kind-less look, which would fail the whole group's
        // decode below and snap every animated key back to base. Inert
        // instead: no kind, no look; every other key keeps its value. The
        // same for a LUT look whose `media` is not a LUT of the project
        // (GR-8: an end is never checked against the media list).
        if let Some(Value::Object(video)) = state.get_mut("video") {
            video.insert("motion".to_string(), to_json(&base_video.motion));
            if video
                .get("look")
                .is_some_and(|look| !look.is_null() && !self.evaluates_as_look(look))
            {
                video.insert("look".to_string(), Value::Null);
            }
            crate::cutout_check::restore_base_video_keys(video, &base_video);
        }
        // A patch that writes a bad type into a field (12.5 into a tick
        // count, say) loses that whole group rather than failing: the
        // evaluator has no way to report, and a base-props frame is far
        // better than a missing one.
        let decoded_video = state
            .get("video")
            .and_then(|v| serde_json::from_value::<VideoProps>(v.clone()).ok());
        let decoded = decoded_video.is_some();
        let evaluated_video = decoded_video.unwrap_or(base_video);
        let evaluated_audio = state
            .get("audio")
            .and_then(|v| serde_json::from_value::<AudioProps>(v.clone()).ok())
            .unwrap_or(base_audio);
        let evaluated_text = clip.text.clone().map(|base| {
            state
                .get("text")
                .and_then(|v| serde_json::from_value::<TextProps>(v.clone()).ok())
                .unwrap_or(base)
        });

        // The clip is in hand here, so the one non-range bound `clamp_video`
        // applies — a nest may not blend — is decided from the source rather
        // than guessed from the props. An adjustment clip's end is closed the
        // same way (spec §11 GR-6).
        let video = {
            let video = clamp_video(evaluated_video, matches!(clip.source, Source::Nest { .. }));
            if is_adjustment(clip) {
                clamp_adjustment(video)
            } else {
                video
            }
        };
        // Two non-identity curves of different counts blend (GR-34), from
        // the final clamped curves — only when the state decoded: a failed
        // decode falls back to the base props, which no action blends from.
        let curve_blends = match spanning {
            Some((target, eased)) if decoded => curve_blends(&video.curves, &target, eased),
            _ => Vec::new(),
        };

        Evaluated {
            video,
            audio: clamp_audio(evaluated_audio),
            text: evaluated_text.map(clamp_text),
            // Shapes are not animatable in version 1: the §5.4 patch is a
            // subset of video/audio/text only, so the description passes
            // through untouched.
            shape: clip.shape.clone(),
            graphic: evaluate_graphic(clip, clip_t),
            curve_blends,
        }
    }

    /// One clip's evaluated state as JSON, for the inspector
    /// (`rc_project_clip_state`). `t` is PROJECT time — the playhead —
    /// which this converts to clip time.
    ///
    /// The keys are the project schema's own (`video`, `audio`, `text`,
    /// `shape`, `graphic`), so the inspector binds to this exactly as it binds to the
    /// clip itself; `in_action` is the action the playhead is inside, or
    /// `null`, which is how the inspector knows an edit would set a
    /// keyframe rather than the base value. `speed` is the rate in force at
    /// that clip time (`rate_in_force`, spec §11 SR-21 (b)).
    ///
    /// `None` for an unknown clip id — the header's NULL return.
    pub fn clip_state(&self, clip_id: u32, t: Ticks) -> Option<Value> {
        let clip = self.clip(clip_id)?;
        let clip_t = t.saturating_sub(clip.start);
        let evaluated = self.evaluate_clip(clip, clip_t);
        let in_action = ordered_actions(clip)
            .into_iter()
            .find(|a| spans(a, clip_t))
            .map(|a| a.id);

        let mut out = Map::new();
        out.insert("clip".to_string(), Value::from(clip.id));
        out.insert("t".to_string(), Value::from(t));
        out.insert(
            "in_action".to_string(),
            in_action.map(Value::from).unwrap_or(Value::Null),
        );
        // The curves as the recipe layer writes them, a blended channel as
        // `{from, to, t}` (GR-34).
        let mut video = video_json(&evaluated.video);
        if let Value::Object(fields) = &mut video {
            let curves = blended_curves_json(&evaluated.video.curves, &evaluated.curve_blends);
            fields.insert("curves".to_string(), curves);
        }
        out.insert("video".to_string(), video);
        out.insert("audio".to_string(), to_json(&evaluated.audio));
        out.insert("text".to_string(), to_json(&evaluated.text));
        out.insert("shape".to_string(), to_json(&evaluated.shape));
        out.insert("graphic".to_string(), to_json(&evaluated.graphic));
        out.insert("speed".into(), rate_in_force(clip, clip_t).into());
        Some(Value::Object(out))
    }
}

